	local onChange = nil
	track(UIS.InputChanged:Connect(function(inp)
		if dragFn and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
			dragFn(inp.Position.X)
		end
	end))
	track(UIS.InputEnded:Connect(function(inp)
		if isPress(inp) then
			holdToken += 1
			dragFn = nil
			scroll.ScrollingEnabled = true
		end
	end))
	local function fmtv(v)
		if math.abs(v) >= 100 then return tostring(math.floor(v + 0.5)) end
		return string.format("%.2f", v)
	end
	local function round(o, r)
		local c = Instance.new("UICorner")
		c.CornerRadius = UDim.new(0, r)
		c.Parent = o
	end
	local function makeRow(y, sp)
		local get, set = accessors(sp)
		local mn, mx, st = sp.mn, sp.mx, sp.st
		label(scroll, sp.label, 11, WHITE, 0, y, 112, 22, Enum.TextXAlignment.Left).ZIndex = 22
		local box = Instance.new("TextBox")
		box.Position = UDim2.fromOffset(150, y)
		box.Size = UDim2.fromOffset(86, 22)
		box.BackgroundColor3 = Color3.fromRGB(4, 6, 10)
		box.BorderSizePixel = 0
		box.TextColor3 = ACC
		box.Font = FONT
		box.TextSize = 12
		box.ClearTextOnFocus = false
		box.ZIndex = 22
		box.Parent = scroll
		round(box, 6)
		local trk = Instance.new("TextButton")
		trk.AutoButtonColor = false
		trk.Text = ""
		trk.BorderSizePixel = 0
		trk.BackgroundColor3 = DIMC
		trk.Position = UDim2.fromOffset(8, y + 31)
		trk.Size = UDim2.fromOffset(276, 10)
		trk.ZIndex = 22
		trk.Parent = scroll
		round(trk, 5)
		local fill = frame(trk, 0, 0, 0, 10, ACC, 0, 5)
		fill.Size = UDim2.new(0, 0, 1, 0)
		fill.ZIndex = 23
		local knob = frame(trk, 0, 0, 18, 18, WHITE, 0, 9)
		knob.AnchorPoint = Vector2.new(0.5, 0.5)
		knob.ZIndex = 24
		local function refresh()
			local v = get()
			box.Text = fmtv(v)
			local rel = math.clamp((v - mn) / (mx - mn), 0, 1)
			fill.Size = UDim2.new(rel, 0, 1, 0)
			knob.Position = UDim2.new(rel, 0, 0.5, 0)
		end
		local function setV(v, loose)
			local span = mx - mn
			if loose then v = math.clamp(v, mn - span, mx + span) else v = math.clamp(v, mn, mx) end
			set(math.floor(v * 1000 + 0.5) / 1000)
			refresh()
			reapply()
			if onChange then onChange() end
		end
		refreshers[#refreshers + 1] = refresh
		refresh()
		for _, d in ipairs({ { "-", 116, -1 }, { "+", 242, 1 } }) do
			local b = button(scroll, d[1], 16, d[2], y, 30, 22, DIMC)
			b.ZIndex = 22
			track(b.InputBegan:Connect(function(inp)
				if not isPress(inp) then return end
				holdToken += 1
				local my = holdToken
				setV(get() + d[3] * st)
				task.spawn(function()
					task.wait(0.4)
					while holdToken == my do
						setV(get() + d[3] * st)
						task.wait(0.05)
					end
				end)
			end))
		end
		local function slideTo(x)
			local rel = math.clamp((x - trk.AbsolutePosition.X) / math.max(trk.AbsoluteSize.X, 1), 0, 1)
			local v = mn + rel * (mx - mn)
			v = math.floor((v - mn) / st + 0.5) * st + mn
			setV(v)
		end
		track(trk.InputBegan:Connect(function(inp)
			if not isPress(inp) then return end
			dragFn = slideTo
			scroll.ScrollingEnabled = false
			slideTo(inp.Position.X)
		end))
		track(box.FocusLost:Connect(function()
			local n = tonumber(box.Text)
			if n then setV(n, true) else refresh() end
		end))
	end
	local function makeToggle(y, sp)
		local b = button(scroll, "", 12, 0, y, 296, 30, DIMC)
		b.ZIndex = 22
		local function txt() b.Text = sp.label .. ": " .. string.upper(T[sp.tog]) .. "  (toque pra trocar)" end
		txt()
		track(b.MouseButton1Click:Connect(function()
			T[sp.tog] = (T[sp.tog] == sp.on) and sp.off or sp.on
			txt()
			reapply()
		end))
	end
	build = function()
		for _, c in ipairs(scroll:GetChildren()) do
			if c:IsA("GuiObject") then c:Destroy() end
		end
		refreshers = {}
		onChange = nil
		local y = 4
		local openY = 0
		local function section(txt)
			label(scroll, "-- " .. txt .. " --", 11, METALC, 0, y + 2, W - 24, 18).ZIndex = 22
			y += 24
		end
		for _, pc in ipairs(PIECES) do
			if pc.cat == cat then
				local isOpen = openKey == pc.key
				local title = (isOpen and "[-]  " or "[+]  ") .. pc.name .. (modified(pc) and "   *" or "")
				local hb = button(scroll, title, 12, 0, y, 296, 30, isOpen and ACC or DIMC, isOpen and Color3.fromRGB(10, 14, 20) or WHITE)
				hb.TextXAlignment = Enum.TextXAlignment.Left
				hb.ZIndex = 22
				local pad = Instance.new("UIPadding")
				pad.PaddingLeft = UDim.new(0, 10)
				pad.Parent = hb
				track(hb.MouseButton1Click:Connect(function()
					openKey = isOpen and nil or pc.key
					task.defer(build)
				end))
				if isOpen then openY = y end
				y += 36
				if isOpen then
					if pc.slot then
						local sw = frame(scroll, 0, y, 296, 18, getC(pc.slot), 0, 6)
						sw.ZIndex = 22
						y += 26
						onChange = function() sw.BackgroundColor3 = getC(pc.slot) end
					end
					if pc.extras then
						for _, sp in ipairs(pc.extras) do
							if sp.tog then
								makeToggle(y, sp)
								y += 38
							else
								makeRow(y, sp)
								y += 48
							end
						end
					end
					if pc.xf then
						section("POSICAO (lado / altura / frente-tras)")
						for _, f in ipairs(POSF) do
							makeRow(y, { label = f[2], grp = pc.key, fld = f[1], mn = f[3], mx = f[4], st = f[5] })
							y += 48
						end
						section("GIRO (graus)")
						for _, f in ipairs(ROTF) do
							makeRow(y, { label = f[2], grp = pc.key, fld = f[1], mn = f[3], mx = f[4], st = f[5] })
							y += 48
						end
						if pc.size then
							section("TAMANHO (1 = normal)")
							for _, f in ipairs(SIZF) do
								makeRow(y, { label = f[2], grp = pc.key, fld = f[1], mn = f[3], mx = f[4], st = f[5] })
								y += 48
							end
						end
						local rb = button(scroll, "ZERAR ESTA PECA", 11, 0, y, 296, 26, DIMC)
						rb.ZIndex = 22
						track(rb.MouseButton1Click:Connect(function()
							resetPiece(pc)
							reapply()
							task.defer(build)
						end))
						y += 34
					end
				end
			end
		end
		scroll.CanvasSize = UDim2.fromOffset(0, y + 8)
		scroll.CanvasPosition = Vector2.new(0, math.max(0, openY - 4))
	end
	setCat("geral")
	local expBox = frame(gui, 0, 0, 320, 250, PANEL, 0.05, 12)
	expBox.AnchorPoint = Vector2.new(0.5, 0.5)
	expBox.Position = UDim2.new(0.5, 0, 0.5, 0)
	expBox.Visible = false
	expBox.ZIndex = 40
	stroke(expBox, 2, ACC, 0.1)
	addScale(expBox, 1)
	label(expBox, "Codigo exportado (copie e cole no topo)", 12, ACC, 0, 4, 320, 18).ZIndex = 41
	local tb = Instance.new("TextBox")
	tb.MultiLine = true
	tb.ClearTextOnFocus = false
	tb.TextEditable = true
	tb.TextXAlignment = Enum.TextXAlignment.Left
	tb.TextYAlignment = Enum.TextYAlignment.Top
	tb.Font = Enum.Font.Code
	tb.TextSize = 11
	tb.TextColor3 = WHITE
	tb.BackgroundColor3 = Color3.fromRGB(4, 6, 10)
	tb.BorderSizePixel = 0
	tb.Position = UDim2.fromOffset(8, 26)
	tb.Size = UDim2.fromOffset(304, 180)
	tb.ZIndex = 41
	tb.Parent = expBox
	local closeB = button(expBox, "FECHAR", 13, 8, 212, 304, 30, DIMC)
	closeB.ZIndex = 41
	track(closeB.MouseButton1Click:Connect(function() expBox.Visible = false end))
	local expB = button(panel, "EXPORTAR", 13, 6, H - 40, 151, 32, ACC, Color3.fromRGB(10, 14, 20))
	expB.ZIndex = 22
	track(expB.MouseButton1Click:Connect(function()
		local txt = exportText()
		tb.Text = txt
		expBox.Visible = true
		local copied = false
		pcall(function()
			local fn = setclipboard or toclipboard or (syn and syn.write_clipboard)
			if fn then fn(txt) copied = true end
		end)
		pcall(print, txt)
		toast(copied and "Codigo COPIADO! Cole acima de  local S = Config.Scale" or "Codigo na tela: segure no texto e copie.", Color3.fromRGB(120, 210, 255))
	end))
	local rstB = button(panel, "RESETAR TUDO", 13, 163, H - 40, 151, 32, DIMC)
	rstB.ZIndex = 22
	track(rstB.MouseButton1Click:Connect(function()
		local D = { DashTop = 3.08, ClusterY = 3.0, ClusterZ = -0.5, WheelY = 3.06, WheelZ = -0.03, WheelScale = 0.82, WheelTilt = 18,
			FuelY = 2.76, FuelZ = 7.02, FuelDia = 0.6, FuelSide = 1, Sunroof = "fechado", SunWidth = 3.3, SeatHeight = 1.25, TopSpeed = 230,
			BodyColor = Color3.fromRGB(34, 35, 41) }
		for k, v in pairs(D) do T[k] = v end
		T.Off = {}
		for n, o in pairs(Config.DefaultOff) do
			T.Off[n] = { px = o.px or 0, py = o.py or 0, pz = o.pz or 0, rx = o.rx or 0, ry = o.ry or 0, rz = o.rz or 0,
				sx = 1, sy = 1, sz = 1, sc = 1 }
		end
		T.Colors = {}
		for n, c in pairs(Config.DefaultColors) do T.Colors[n] = c end
		build()
		reapply()
	end))
	local tgl = button(gui, "EDITAR", 12, 0, 0, 64, 28, PANEL)
	tgl.AnchorPoint = Vector2.new(1, 0)
	tgl.Position = UDim2.new(1, -8, 0, 8)
	tgl.ZIndex = 20
	addScale(tgl, 1)
	__editorToggle = function() panel.Visible = not panel.Visible end
	track(tgl.MouseButton1Click:Connect(__editorToggle))
end
track(UIS.InputBegan:Connect(function(input)
	if UIS:GetFocusedTextBox() then return end
	local k = input.KeyCode
	if k == Enum.KeyCode.G then
		if __editorToggle then __editorToggle() end
	elseif k == Enum.KeyCode.M then
		if car then despawnCar() else spawnCar() end
	elseif k == Enum.KeyCode.F then
		if car then
			if car.driver then
				exitCar(car)
			else
				local _, _, rpart = charParts()
				if rpart and (rpart.Position - car.pos).Magnitude < Config.BoardRadius * S then enterCar(car) end
			end
		end
	elseif car and car.setShell and (k == Enum.KeyCode.One or k == Enum.KeyCode.Two or k == Enum.KeyCode.Three or k == Enum.KeyCode.Four) then
		local n = (k == Enum.KeyCode.One and 1) or (k == Enum.KeyCode.Two and 2) or (k == Enum.KeyCode.Three and 3) or 4
		Config.ShellStyle = n
		car.setShell(n)
		pcall(toast, "Carroceria: " .. tostring(car.shellName))
	elseif car and car.driver then
		if k == Enum.KeyCode.P then
			if car.mode == "P" and not car.parkPending then setMode("N") else setMode("P") end
		elseif k == Enum.KeyCode.R then
			setMode("R")
		elseif k == Enum.KeyCode.N then
			setMode("N")
		elseif k == Enum.KeyCode.Z then
			local i = modeIndex(car.parkPending and "P" or car.mode)
			if i > 1 then setMode(MODES[i - 1]) end
		elseif k == Enum.KeyCode.X then
			local i = modeIndex(car.parkPending and "P" or car.mode)
			if i < #MODES then setMode(MODES[i + 1]) end
		elseif k == Enum.KeyCode.E then
			setGear(gear + 1)
		elseif k == Enum.KeyCode.Q then
			setGear(gear - 1)
		elseif k == Enum.KeyCode.L then
			car.lamps = not car.lamps
		elseif k == Enum.KeyCode.B or k == Enum.KeyCode.Space then
			held.brake = true
		end
	end
end))
track(UIS.InputEnded:Connect(function(input)
	if input.KeyCode == Enum.KeyCode.B or input.KeyCode == Enum.KeyCode.Space then
		held.brake = false
	end
end))
track(player.CharacterAdded:Connect(function()
	if car and car.driver then
		car.driver = false
		car.boardFrom = nil
		saved = nil
		setMode("P", true)
	end
end))
local ARMS = { on = false, w = 0, lean = 0, J = nil, waist = nil, ang = {} }
local GRIP_A = math.rad(62)
local GRIP_PERIOD = 2.0

local function armRotFromTo(a, b)
	a, b = a.Unit, b.Unit
	local axis = a:Cross(b)
	local dp = a:Dot(b)
	if axis.Magnitude < 1e-5 then
		if dp > 0 then return CFrame.new() end
		local perp = math.abs(a.X) < 0.9 and Vector3.xAxis or Vector3.yAxis
		return CFrame.fromAxisAngle(a:Cross(perp).Unit, math.pi)
	end
	return CFrame.fromAxisAngle(axis.Unit, math.acos(math.clamp(dp, -1, 1)))
end

local function armJoints(ch)
	local J = { right = { extra = {} }, left = { extra = {} } }
	local names = { right = { "RightUpperArm", "Right Arm" }, left = { "LeftUpperArm", "Left Arm" } }
	local motors = {}
	for _, d in ipairs(ch:GetDescendants()) do
		if d:IsA("Motor6D") and d.Part0 and d.Part1 then
			motors[#motors + 1] = d
			for side, list in pairs(names) do
				if d.Part1.Name == list[1] or d.Part1.Name == list[2] then
					J[side].shoulder = J[side].shoulder or d
				end
			end
		end
	end
	for _, j in pairs(J) do
		local cur = j.shoulder
		for _ = 1, 2 do
			if not cur then break end
			local nxt
			for _, m in ipairs(motors) do
				if m ~= cur and m.Part0 == cur.Part1 and not m.Part1:IsA("Accessory") then
					local nm = m.Part1.Name:lower()
					if nm:find("arm") or nm:find("hand") or nm:find("elbow") or nm:find("wrist") then nxt = m break end
				end
			end
			if not nxt then break end
			table.insert(j.extra, nxt)
			if not j.elbow then j.elbow = nxt else j.hand = nxt end
			cur = nxt
		end
	end
	return J
end

local function armChain(j)
	local sh = j.shoulder
	if not (sh and sh.Parent and sh.Part0 and sh.Part1) then return nil end
	local function rot(cf) return cf - cf.Position end
	local elbow, hand = j.elbow, j.hand
	if elbow and not (elbow.Parent and elbow.Part0 == sh.Part1 and elbow.Part1) then elbow = nil end
	if hand and not (elbow and hand.Parent and hand.Part0 == elbow.Part1 and hand.Part1) then hand = nil end
	local rrSh = rot(sh.C0) * rot(sh.C1):Inverse()
	local v1 = elbow and (elbow.C0.Position - sh.C1.Position) or Vector3.new(0, -1, 0)
	if v1.Magnitude < 1e-3 then v1 = Vector3.new(0, -1, 0) end
	local k = { sh = sh, elbow = elbow, rrSh = rrSh, d0 = rrSh * v1, L1 = sh.Part1.Size.Y * 0.95 }
	if elbow then
		k.L1 = (elbow.C0.Position - sh.C1.Position).Magnitude
		k.L2 = elbow.Part1.Size.Y * 0.9
		local v2 = Vector3.new(0, -1, 0)
		if hand then
			local hv = hand.C0.Position - elbow.C1.Position
			if hv.Magnitude > 1e-3 then v2 = hv end
			k.L2 = hv.Magnitude + hand.Part1.Size.Y * 0.4
		end
		k.rrEl = rot(elbow.C0) * rot(elbow.C1):Inverse()
		k.d2 = k.rrEl * v2
	end
	k.reach = (k.L2 and (k.L1 + k.L2) or k.L1) * 0.97
	return k
end

local function solveArm(k, p0n, tgt, sgn, bodyRight, bodyUp, bodyBack, ez)
	local sh, elbow = k.sh, k.elbow
	local P = p0n * sh.C0.Position
	local toT = tgt - P
	local dist = toT.Magnitude
	if dist < 0.05 then return end
	local dirT = toT / dist
	local uW, lW = dirT, nil
	if k.L2 then
		local L1, L2 = k.L1, k.L2
		local d = math.min(dist, (L1 + L2) * 0.999)
		local a = (L1 * L1 - L2 * L2 + d * d) / (2 * d)
		local h = math.sqrt(math.max(L1 * L1 - a * a, 0))
		local pole = bodyRight * (0.45 * sgn) - bodyUp + bodyBack * 0.2
		pole = pole - dirT * pole:Dot(dirT)
		pole = pole.Magnitude > 1e-3 and pole.Unit or -bodyUp
		local E = P + dirT * a + pole * h
		uW = (E - P).Unit
		local lv = (P + dirT * d) - E
		lW = lv.Magnitude > 1e-3 and lv.Unit or uW
	end
	local R = armRotFromTo(k.d0, p0n:VectorToObjectSpace(uW))
	local CF1 = CFrame.new(sh.C0.Position) * R * k.rrSh * CFrame.new(-sh.C1.Position)
	local B = sh.C0:Inverse() * CF1 * sh.C1
	sh.Transform = sh.Transform:Lerp(B, ez)
	if elbow and lW and k.d2 then
		local upperCF = p0n * CF1
		local R2 = armRotFromTo(k.d2, upperCF:VectorToObjectSpace(lW))
		local CF2 = CFrame.new(elbow.C0.Position) * R2 * k.rrEl * CFrame.new(-elbow.C1.Position)
		local eb = elbow.C0:Inverse() * CF2 * elbow.C1
		elbow.Transform = CFrame.new():Lerp(eb, ez)
	end
end

local function releaseArms()
	if not ARMS.on then return end
	ARMS.on = false
	ARMS.w = 0
	ARMS.ang = {}
	if ARMS.lean > 0 then
		ARMS.lean = 0
		if ARMS.waist and ARMS.waist.Parent then ARMS.waist.Transform = CFrame.new() end
	end
	local J = ARMS.J
	ARMS.J = nil
	ARMS.waist = nil
	if not J then return end
	for _, side in pairs(J) do
		if side.shoulder and side.shoulder.Parent then side.shoulder.Transform = CFrame.new() end
		for _, m in ipairs(side.extra) do
			if m.Parent then m.Transform = CFrame.new() end
		end
	end
end

local function driveArms(c, dt)
	local ch, hum, rpart = charParts()
	if not (ch and c.driver) then
		releaseArms()
		return
	end
	if c.boardFrom then return end
	if not ARMS.J or not ARMS.J.right.shoulder or not ARMS.J.right.shoulder.Parent then
		ARMS.J = armJoints(ch)
		ARMS.waist = nil
		ARMS.lean = 0
	end
	local J = ARMS.J
	local chR, chL = armChain(J.right), armChain(J.left)
	if not (chR and chL) then return end
	ARMS.on = true
	ARMS.w = math.min(1, ARMS.w + dt * 4)
	local ez = ARMS.w * ARMS.w * (3 - 2 * ARMS.w)

	local seatW = c.cf * SEAT_REL
	local rootInv = rpart.CFrame:Inverse()
	local function pw(part) return seatW * (rootInv * part.CFrame) end
	local bodyRight, bodyUp, bodyBack = seatW.RightVector, seatW.UpVector, -seatW.LookVector

	local baseCF = c.cf * c.swBase
	local rim = 0.62 * S
	local off = ((c.steer * 2.6 + GRIP_PERIOD / 2) % GRIP_PERIOD) - GRIP_PERIOD / 2
	local grips = {}
	for _, sd in ipairs({ "right", "left" }) do
		local sgn = sd == "right" and 1 or -1
		local tA = sgn * GRIP_A + off
		local cur = ARMS.ang[sd] or tA
		cur = cur + (tA - cur) * math.min(1, dt * 16)
		ARMS.ang[sd] = cur
		grips[sd] = baseCF * Vector3.new(0, rim * math.cos(cur), rim * math.sin(cur))
	end

	for _, side in pairs(J) do
		for _, m in ipairs(side.extra) do
			if m.Parent then m.Transform = CFrame.new() end
		end
	end

	local sr = chR.sh
	local waist = ARMS.waist
	if waist == nil or (waist and (not waist.Parent or waist.Part1 ~= sr.Part0)) then
		waist = false
		local scope = sr.Part0:FindFirstAncestorOfClass("Model") or sr.Part0.Parent
		for _, d in ipairs(scope:GetDescendants()) do
			if d:IsA("Motor6D") and d.Part1 == sr.Part0 and d.Part0 then waist = d break end
		end
		ARMS.waist = waist
	end

	local prevLean = ARMS.lean
	local spin = nil
	if waist and waist.Parent and waist.Part0 then
		local lowerCF = pw(waist.Part0)
		local Wp = lowerCF * waist.C0.Position
		spin = function(th)
			return CFrame.new(Wp) * CFrame.fromAxisAngle(bodyRight, -th) * CFrame.new(-Wp)
		end
		local p0u = spin(prevLean):Inverse() * pw(sr.Part0)
		local need = 0
		for i = 0, 10 do
			local th = i * 0.05
			need = th
			if ((spin(th) * p0u) * sr.C0.Position - grips.right).Magnitude <= chR.reach then break end
		end
		local lean = prevLean + (need * ez - prevLean) * math.min(1, dt * 10)
		if lean > 0.002 then
			local a0 = lowerCF:VectorToObjectSpace(bodyRight)
			local aC = (waist.C0 - waist.C0.Position):Inverse() * a0
			waist.Transform = CFrame.fromAxisAngle(aC, -lean)
		end
		ARMS.lean = lean
	end

	local function p0nOf(sh)
		local p0w = pw(sh.Part0)
		if spin then return spin(ARMS.lean) * (spin(prevLean):Inverse() * p0w) end
		return p0w
	end
	solveArm(chR, p0nOf(chR.sh), grips.right, 1, bodyRight, bodyUp, bodyBack, ez)
	solveArm(chL, p0nOf(chL.sh), grips.left, -1, bodyRight, bodyUp, bodyBack, ez)
end
track(player.CharacterAdded:Connect(function()
	ARMS.on = false
	ARMS.w = 0
	ARMS.lean = 0
	ARMS.J = nil
	ARMS.waist = nil
	ARMS.ang = {}
end))
local STEP_ID = "ChargerStep"
pcall(function() RunService:UnbindFromRenderStep(STEP_ID) end)
RunService:BindToRenderStep(STEP_ID, Enum.RenderPriority.Camera.Value - 2, function(dt)
	dt = math.clamp(dt, 1 / 240, 0.05)
	local c = car
	if c and c.model.Parent then
		filterT = filterT - dt
		if filterT <= 0 then
			filterT = 0.5
			refreshFilter()
		end
		stepCar(c, dt)
		carVisuals(c, dt)
		if c.driver then
			holdChar(c)
			pcall(driveArms, c, dt)
		elseif ARMS.on then
			pcall(releaseArms)
		end
	else
		if ARMS.on then pcall(releaseArms) end
		if c then car = nil end
	end
	updateHud(dt)
end)
genv[CLEANUP_KEY] = function()
	pcall(function() RunService:UnbindFromRenderStep(STEP_ID) end)
	pcall(releaseArms)
	pcall(despawnCar)
	pcall(K.destroy)
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	pcall(function() gui:Destroy() end)
	pcall(function() if skidFolder then skidFolder:Destroy() end end)
	genv[CLEANUP_KEY] = nil
end
toast("CHARGER pronto  -  use a CHAVE (ou tecla M)", Color3.fromRGB(120, 210, 255))
end, debug.traceback)
if not __ok then
	pcall(warn, "[Charger] erro:", __err)
end
